.product-guide { --pg-green:#0d5c36; --pg-soft:#f2f7f4; --pg-line:#dce8e1; }
.pg-disclosure { display:grid; grid-template-columns:max-content minmax(0,1fr); column-gap:18px; row-gap:6px; align-items:start; padding:17px 20px; margin:0 0 24px; border:1px solid var(--pg-line); border-radius:12px; background:var(--pg-soft); font-size:14px; line-height:1.55; }
.pg-disclosure strong { color:var(--pg-green); white-space:nowrap; line-height:1.55; }
.pg-disclosure span { min-width:0; overflow-wrap:anywhere; }
.pg-intro { margin-bottom:28px; }
.pg-quick-picks { border:1px solid var(--pg-line); border-radius:14px; padding:18px; margin:0 0 28px; background:#fff; }
.pg-quick-picks h2 { margin:0 0 14px; font:700 18px/1.2 system-ui,sans-serif; color:var(--pg-green); text-transform:uppercase; letter-spacing:.04em; }
.pg-quick-picks ol { list-style:none; padding:0; margin:0; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px 18px; }
.pg-quick-picks li { display:grid; grid-template-columns:28px 44px 1fr; gap:9px; align-items:center; min-width:0; }
.pg-quick-picks img { display:block; width:44px; height:44px; object-fit:contain; object-position:center; }
.pg-quick-picks a { color:var(--text); text-decoration:none; font-weight:650; line-height:1.25; }
.pg-rank { width:26px; height:26px; border-radius:50%; display:grid; place-items:center; background:var(--pg-green); color:#fff; font-weight:800; font-size:12px; }
.pg-product-card { box-sizing:border-box; display:grid; grid-template-columns:minmax(170px,30%) minmax(0,1fr); gap:24px; width:100%; max-width:100%; min-width:0; overflow:hidden; padding:22px; margin:0 0 18px; border:1px solid var(--pg-line); border-radius:16px; background:#fff; box-shadow:0 8px 28px rgba(20,55,39,.06); }
.pg-product-image { box-sizing:border-box; display:grid; place-items:center; align-self:start; width:min(100%,280px); max-width:280px; min-width:0; height:240px; max-height:240px; margin:0 auto; overflow:hidden; padding:14px; border-radius:12px; background:#fafcfb; contain:layout paint; line-height:0; }
.pg-product-image img { display:block!important; width:auto!important; height:auto!important; min-width:0!important; min-height:0!important; max-width:100%!important; max-height:100%!important; aspect-ratio:auto!important; object-fit:contain!important; object-position:center!important; margin:auto!important; }
.pg-product-copy h2 { margin:7px 0 8px; font-family:"Fraunces",serif; font-size:25px; line-height:1.2; }
.pg-product-copy p { margin:0 0 12px; font-size:16px; line-height:1.65; }
.pg-label { display:inline-block; padding:4px 8px; border-radius:5px; background:var(--pg-green); color:#fff; font-size:10px; font-weight:800; letter-spacing:.05em; text-transform:uppercase; }
.pg-best-for { color:var(--text-secondary); }
.pg-reasons { margin:10px 0 18px; padding:0; list-style:none; }
.pg-reasons li { position:relative; padding-left:22px; margin:7px 0; line-height:1.45; }
.pg-reasons li::before { content:'✓'; position:absolute; left:0; color:var(--pg-green); font-weight:900; }
.pg-amazon-button { display:inline-flex; align-items:center; justify-content:center; min-height:44px; padding:10px 18px; border-radius:8px; background:var(--pg-green); color:#fff!important; text-decoration:none!important; font-weight:800; box-shadow:0 5px 14px rgba(13,92,54,.18); }
.pg-comparison { box-sizing:border-box; width:100%; max-width:100%; overflow-x:auto; -webkit-overflow-scrolling:touch; overscroll-behavior-inline:contain; margin:34px 0; border:1px solid var(--pg-line); border-radius:14px; }
.pg-comparison h2 { margin:0; padding:15px 18px; background:var(--pg-soft); color:var(--pg-green); font:800 16px/1.2 system-ui,sans-serif; text-transform:uppercase; letter-spacing:.04em; }
.pg-comparison table { width:100%; min-width:760px; border-collapse:collapse; table-layout:auto; font-size:13px; }
.pg-comparison th,.pg-comparison td { padding:12px 14px; border-top:1px solid var(--pg-line); text-align:left; vertical-align:top; overflow-wrap:normal!important; word-break:normal!important; hyphens:none!important; }
.pg-comparison th { color:var(--pg-green); font-size:11px; text-transform:uppercase; letter-spacing:.04em; white-space:nowrap; }
.pg-comparison th:nth-child(1),.pg-comparison td:nth-child(1) { min-width:190px; }
.pg-comparison th:nth-child(2),.pg-comparison td:nth-child(2) { min-width:260px; }
.pg-comparison th:nth-child(3),.pg-comparison td:nth-child(3) { min-width:180px; }
.pg-comparison th:nth-child(4),.pg-comparison td:nth-child(4) { min-width:110px; white-space:nowrap; }
.pg-closing { padding:22px; border-left:5px solid var(--pg-green); border-radius:0 12px 12px 0; background:var(--pg-soft); }
@media(max-width:720px) {
 .pg-disclosure { grid-template-columns:1fr; gap:5px; padding:15px 16px; font-size:13px; line-height:1.5; }
 .pg-disclosure strong { white-space:normal; }
 .pg-quick-picks ol { grid-template-columns:1fr; }
 .pg-product-card { grid-template-columns:minmax(0,1fr); width:100%; max-width:100%; padding:17px; }
 .pg-product-image { width:min(100%,220px); max-width:220px; height:190px; max-height:190px; margin:0 auto; overflow:hidden; padding:10px; }
 .pg-product-image img { width:auto!important; height:auto!important; min-width:0!important; min-height:0!important; max-width:100%!important; max-height:100%!important; aspect-ratio:auto!important; object-fit:contain!important; object-position:center!important; margin:auto!important; }
 .pg-product-copy h2 { font-size:23px; }
 .pg-amazon-button { width:100%; }
 .pg-comparison table { min-width:760px; }
 .pg-comparison th,.pg-comparison td { overflow-wrap:normal!important; word-break:normal!important; hyphens:none!important; }
}

